{
  "findings": [
    {
      "check_id": "CKV_GCP_62",
      "title": "Cloud Storage access logging is not enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket has no logging block, so access requests to compliance data are not recorded in a configured log bucket for security monitoring and investigation."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Uniform bucket-level access is not enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Without uniform bucket-level access, legacy object ACLs can grant permissions outside the bucket's IAM policy and make access control harder to audit."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Public access prevention is not enforced",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce public access prevention, allowing a future IAM or ACL change to expose compliance data publicly."
    }
  ],
  "patched_code": "variable "compliance_access_log_bucket_name" {
  description = "Name of an existing secured Cloud Storage bucket configured to receive access logs."
  type        = string
}

resource "google_storage_bucket" "compliance_storage" {
  name                        = "${var.project_id}-digital-asset-trading-platform-compliance"
  location                    = var.region
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  logging {
    log_bucket        = var.compliance_access_log_bucket_name
    log_object_prefix = "compliance-storage-access-logs/"
  }

  versioning {
    enabled = true
  }

  lifecycle_rule {
    condition {
      age = 2555
    }
    action {
      type = "Delete"
    }
  }
}
",
  "fix_summary": "Enabled uniform bucket-level access and enforced public access prevention. Added access logging to a caller-supplied, preconfigured secure log bucket without introducing placeholder credentials or secrets."
}
